class Main {
    public static void main(String[] args) {
        // 몇까지 더할지 입력받아요.
        var scanner = new java.util.Scanner(System.in, "UTF-8");
        int n = scanner.nextInt();
        int sum = 0;
        // 누적 변수는 반복 밖에서 한 번만 만들어요.
        for (int i = 1; i <= n; i++) {
            sum += i;
        }
        System.out.println(sum);
    }
}
